'use strict';
const attendanceDrafts=new Map();let attendanceShownKey=null;
function selectedEmptyCity(){const ref=selectedMapItem;if(ref?.kind!=='slot')return null;const s=slotBy(ref.id);return s&&!memberAt(s.id)?s:null}
function queueTrap(){return selectedEmptyCity()?.trap||+state.operations.rosterGroup}
function assignQueuedPlayer(id){try{const m=state.members.find(m=>m.id===id);if(!m||!m.trap){memberDetail(id);return}const target=Hive.nextAvailableCity(state,m.trap,selectedEmptyCity()?.id);if(!target){toast('Add a city space or choose a layout first.');return}const next=Hive.assignAvailableSlotMember(state,target.id,id);commit(()=>state=next);selectedMapItem={kind:'member',id};selectedSlot=target.id;renderMap();renderQueue();toast(m.name+' placed. Undo is available.')}catch(e){toast(e.message)}}
renderQueue=function(){const trap=queueTrap();$$('#queueTrapTabs button').forEach(b=>b.classList.toggle('active',+b.dataset.queueTrap===trap));const q=$('#queueSearch').value||'',group=trap?Hive.slotAttendanceGroup(state,trap,{query:q}):null,list=trap?group.members:state.members.filter(m=>!m.trap&&!m.slot&&(m.name+' '+m.playerId).toLocaleLowerCase().includes(q.toLocaleLowerCase()));$('#queueHeading').textContent=selectedEmptyCity()?'Who goes here?':'Players to place';$('#queueGroupLabel').textContent=group?.kind?group.label+' · '+group.groupCount:trap?'':'Choose a BT group to place these players.';const html=list.map(m=>`<button class="queue-row" ${readonly?'disabled':''} data-queue-player="${esc(m.id)}"><span>${esc(m.name)}</span><small>${trap?'Place →':'Edit player →'}</small></button>`).join('')||`<p class="muted">${group?.remaining?'No matches in this attendance group.':state.members.some(m=>m.trap===trap)?'All players for this trap are assigned.':'Add players in Players to get started.'}</p>`;if($('#queue').innerHTML!==html){$('#queue').innerHTML=html;$$('[data-queue-player]').forEach(b=>b.onclick=()=>assignQueuedPlayer(b.dataset.queuePlayer))}$('#suggestBtn').disabled=readonly||!trap||!Hive.slotAttendanceGroup(state,trap).remaining||!Hive.nextAvailableCity(state,trap);};
$('#queueSearch').oninput=renderQueue;
$('#suggestBtn').onclick=()=>{try{const result=Hive.placeUnassignedPlayers(state,queueTrap());if(!result.placed.length){toast('No empty, valid city spaces are available.');return}commit(()=>state=result.state);selectedMapItem=null;selectedSlot=null;renderMap();renderQueue();toast(result.placed.length+' players placed. Undo is available.')}catch(e){toast(e.message)}};
// Keep the active item tool visible without adding permanent toolbar buttons.
const simpleTool=setTool;setTool=function(t){simpleTool(t);$('#itemMenu').open=false;$('#itemMenu').classList.toggle('active',['flag','block','hq'].includes(t));$('#itemMenu').setAttribute('aria-label',['flag','block','hq'].includes(t)?'Add item · '+({flag:'Banner',block:'Terrain',hq:'HQ'})[t]+' selected':'Add item')};
$$('[data-tool]').forEach(b=>b.onclick=()=>{togglePlacementTool(b.dataset.tool);renderQueue()});
const simpleQueueTabs=renderQueueTabs;renderQueueTabs=function(){simpleQueueTabs();$$('[data-queue-trap]').forEach(b=>{const choose=b.onclick;b.onclick=()=>{selectedMapItem=null;selectedSlot=null;choose();focusPlanningMap()}})};
function attendanceDraft(){const o=state.operations,key=Hive.attendanceSessionKey(o.date,o.trap),r=Hive.attendanceSession(state),token=JSON.stringify(r||null),old=attendanceDrafts.get(key);if(old&&old.token===token){if(!r)state.members.filter(m=>m.trap===o.trap).forEach(m=>old.eligible.add(m.id));return old;}const draft={key,token,checked:new Set(r?.attended||[]),eligible:new Set(r?.eligible||state.members.filter(m=>m.trap===o.trap).map(m=>m.id)),complete:!!r?.complete,query:''};attendanceDrafts.set(key,draft);return draft}
function attendancePeople(draft){return state.members.filter(m=>m.trap===state.operations.trap||draft.checked.has(m.id)||draft.eligible.has(m.id)).sort((a,b)=>a.name.localeCompare(b.name))}
function updateAttendanceSave(){const d=attendanceDraft();$('#saveSimpleAttendance').textContent='Save '+attendeeLabel(d.checked.size);$('#attendanceDraftCount').textContent=d.checked.size+' selected';}
function renderAttendanceNames(){const d=attendanceDraft(),q=d.query.trim().toLocaleLowerCase(),people=attendancePeople(d).filter(m=>!q||(m.name+' '+m.playerId).toLocaleLowerCase().includes(q));$('#attendanceNames').innerHTML=people.map(m=>`<label class="attendance-name"><input type="checkbox" data-simple-attendee="${esc(m.id)}" ${d.checked.has(m.id)?'checked':''} ${readonly?'disabled':''}><span>${esc(m.name)}</span>${m.trap!==state.operations.trap?'<small>Other group</small>':''}</label>`).join('')||'<p class="muted">'+(q?'No matching players.':'Add players in Players, or paste attendee names below.')+'</p>';$$('[data-simple-attendee]').forEach(el=>el.onchange=()=>{if(el.checked){d.checked.add(el.dataset.simpleAttendee);d.eligible.add(el.dataset.simpleAttendee)}else d.checked.delete(el.dataset.simpleAttendee);updateAttendanceSave()})}
renderAttendance=function(){const o=state.operations,r=Hive.attendanceSession(state),d=attendanceDraft();if(attendanceShownKey!==d.key){$('#attendanceSavedReceipt').classList.add('hidden');attendanceShownKey=d.key;}$('#attendanceSummary').innerHTML=`<div class="attendance-heading"><h2>Who attended BT ${o.trap}?</h2><p>${attendanceDateLabel(o.date,true)} · ${esc(state.settings['time'+o.trap])} UTC</p><small>${r?.complete?'Complete':r?'Partial':'Not recorded'} · ${r?.attended.length||0} saved · Every 2 days</small></div>`;$('#attendanceSession').innerHTML=`<section class="card simple-attendance"><label>Find a player<input id="attendanceNameSearch" type="search" placeholder="Name or player ID" value="${esc(d.query)}"></label><div id="attendanceNames"></div><div class="attendance-list-state"><label class="check"><input id="simpleComplete" type="checkbox" ${d.complete?'checked':''} ${readonly?'disabled':''}> This is the full list</label><small>Unlisted eligible players count as absent only for a full list.</small></div><div class="attendance-save"><small id="attendanceDraftCount"></small><button class="primary" id="saveSimpleAttendance" ${readonly?'disabled':''}>Save attendees</button></div></section>`;$('#attendanceNameSearch').oninput=e=>{d.query=e.target.value;renderAttendanceNames()};$('#simpleComplete').onchange=e=>d.complete=e.target.checked;$('#saveSimpleAttendance').onclick=()=>{try{const next=Hive.saveAttendanceSession(state,{date:o.date,trap:o.trap,selected:[...d.checked],eligible:[...d.eligible],complete:d.complete,replace:true});commit(()=>state=next);attendanceReceipt();toast('Saved '+attendeeLabel(d.checked.size)+' to '+attendanceDestination()+'.')}catch(e){toast(e.message)}};renderAttendanceNames();updateAttendanceSave();const logs=Object.values(state.attendanceLog.sessions).filter(x=>x.trap===o.trap).sort((a,b)=>b.date.localeCompare(a.date));$('#attendanceHistory').innerHTML=logs.map(x=>`<button class="history-row" data-session-date="${esc(x.date)}"><strong>${esc(x.date)}</strong><span>${x.attended.length} attended</span><span class="pill">${x.complete?'Complete':'Partial'}</span></button>`).join('')||'<p class="muted">No saved events yet.</p>';$$('[data-session-date]').forEach(b=>b.onclick=()=>{commit(()=>state.operations.date=b.dataset.sessionDate);$('#attendanceSession').scrollIntoView?.({behavior:'smooth',block:'start'})})};
// Default phone framing favours legible cities. Fit still shows the full layout.
function focusPlanningMap(){if(page!=='map'||activeTrap==='all'||!window.matchMedia?.('(max-width:720px)').matches)return;const t=state.traps.find(t=>String(t.id)===activeTrap);if(!t)return;const p=projected(t.x+t.w/2,t.y+t.h/2);camera.k=Math.max(camera.k,30);camera.x=view.w/2-p.x*camera.k;camera.y=view.h/2-p.y*camera.k;renderMap()}
$$('#trapTabs button,[data-map-mode]').forEach(b=>{const prior=b.onclick;b.onclick=()=>{prior();focusPlanningMap()}});
const simpleNavigate=navigate;navigate=function(p){simpleNavigate(p);if(p==='map')setTimeout(focusPlanningMap,10)};
render();setTimeout(focusPlanningMap,35);
